module shuffle_number #(\n    parameter N = 8,\n    parameter DATA_WIDTH = 4,\n    parameter RESULT_WIDTH = 3\n)(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [DATA_WIDTH-1:0] perm_0,\n    input wire [DATA_WIDTH-1:0] perm_1,\n    input wire [DATA_WIDTH-1:0] perm_2,\n    input wire [DATA_WIDTH-1:0] perm_3,\n    input wire [DATA_WIDTH-1:0] perm_4,\n    input wire [DATA_WIDTH-1:0] perm_5,\n    input wire [DATA_WIDTH-1:0] perm_6,\n    input wire [DATA_WIDTH-1:0] perm_7,\n    output reg [RESULT_WIDTH-1:0] result,\n    output reg done\n);\n\n    // Internal arrays\n    reg [2:0] pos [0:N-1];\n    reg [0:0] inc [0:N-2];\n    reg [2:0] f [0:N-1][0:N-1];\n\n    // State definitions\n    localparam [3:0] IDLE = 4'd0;\n    localparam [3:0] INIT_POS_START = 4'd1;\n    localparam [3:0] INIT_POS_LOOP = 4'd2;\n    localparam [3:0] INIT_INC_START = 4'd3;\n    localparam [3:0] INIT_INC_LOOP = 4'd4;\n    localparam [3:0] DP_START = 4'd5;\n    localparam [3:0] DP_INIT = 4'd6;\n    localparam [3:0] DP_LEN_LOOP = 4'd7;\n    localparam [3:0] DP_L_LOOP = 4'd8;\n    localparam [3:0] DP_M_LOOP = 4'd9;\n    localparam [3:0] DP_UPDATE = 4'd10;\n    localparam [3:0] DONE = 4'd11;\n\n    reg [3:0] state;\n    reg [2:0] len_cnt;\n    reg [2:0] l_cnt;\n    reg [2:0] m_cnt;\n    reg [2:0] best;\n    reg [2:0] temp;\n\n    // Helper to access perm array\n    wire [DATA_WIDTH-1:0] perm [0:N-1];\n    assign perm[0] = perm_0;\n    assign perm[1] = perm_1;\n    assign perm[2] = perm_2;\n    assign perm[3] = perm_3;\n    assign perm[4] = perm_4;\n    assign perm[5] = perm_5;\n    assign perm[6] = perm_6;\n    assign perm[7] = perm_7;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 3'd0;\n            len_cnt <= 3'd0;\n            l_cnt <= 3'd0;\n            m_cnt <= 3'd0;\n            best <= 3'd0;\n            temp <= 3'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= INIT_POS_START;\n                    end\n                end\n\n                INIT_POS_START: begin\n                    l_cnt <= 3'd0;\n                    state <= INIT_POS_LOOP;\n                end\n\n                INIT_POS_LOOP: begin\n                    if (l_cnt < N) begin\n                        pos[ perm[l_cnt] - 1 ] <= l_cnt;\n                        l_cnt <= l_cnt + 3'd1;\n                    end else begin\n                        state <= INIT_INC_START;\n                    end\n                end\n\n                INIT_INC_START: begin\n                    l_cnt <= 3'd0;\n                    state <= INIT_INC_LOOP;\n                end\n\n                INIT_INC_LOOP: begin\n                    if (l_cnt < N-1) begin\n                        if (pos[l_cnt] < pos[l_cnt+1])\n                            inc[l_cnt] <= 1'b1;\n                        else\n                            inc[l_cnt] <= 1'b0;\n                        l_cnt <= l_cnt + 3'd1;\n                    end else begin\n                        state <= DP_START;\n                    end\n                end\n\n                DP_START: begin\n                    l_cnt <= 3'd0;\n                    state <= DP_INIT;\n                end\n\n                DP_INIT: begin\n                    if (l_cnt < N) begin\n                        f[l_cnt][l_cnt] <= 3'd0;\n                        l_cnt <= l_cnt + 3'd1;\n                    end else begin\n                        len_cnt <= 3'd2;\n                        state <= DP_LEN_LOOP;\n                    end\n                end\n\n                DP_LEN_LOOP: begin\n                    if (len_cnt <= N) begin\n                        l_cnt <= 3'd0;\n                        state <= DP_L_LOOP;\n                    end else begin\n                        result <= f[0][N-1];\n                        state <= DONE;\n                    end\n                end\n\n                DP_L_LOOP: begin\n                    if (l_cnt <= N - len_cnt) begin\n                        best <= 3'd7;\n                        m_cnt <= l_cnt;\n                        state <= DP_M_LOOP;\n                    end else begin\n                        len_cnt <= len_cnt + 3'd1;\n                        state <= DP_LEN_LOOP;\n                    end\n                end\n\n                DP_M_LOOP: begin\n                    if (m_cnt <= l_cnt + len_cnt - 2) begin\n                        if (f[l_cnt][m_cnt] > f[m_cnt+1][l_cnt+len_cnt-1])\n                            temp <= f[l_cnt][m_cnt];\n                        else\n                            temp <= f[m_cnt+1][l_cnt+len_cnt-1];\n                        state <= DP_UPDATE;\n                    end else begin\n                        f[l_cnt][l_cnt+len_cnt-1] <= best;\n                        l_cnt <= l_cnt + 3'd1;\n                        state <= DP_L_LOOP;\n                    end\n                end\n\n                DP_UPDATE: begin\n                    if (temp + 3'd1 < best)\n                        best <= temp + 3'd1;\n                    m_cnt <= m_cnt + 3'd1;\n                    state <= DP_M_LOOP;\n                end\n\n                DONE: begin\n                    done <= 1'b1;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule